head.script:
scwin.cal_onviewchange = function(info) {
    cal2.focus();
};
scwin.cal_oniconclick = function() {
    cal2.focus();
};
scwin.isFocus = function() {
    return WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id + 'cal2_input')).is(':focus');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 왼쪽의 inputCalendar에서 날짜를 직접입력하고(20160822) 마우스를 Focusout시킨다.
    //1. After running the sample file, input the date directly in the inputCalendar on the left (20160822) and focus the mouse.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal_input').focus()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal_input').value = '20160822'");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cal_input').blur()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. 날짜가 입력되어지고 Focus가 오른쪽의 inputCalendar로 이동되어진다.(이전에는 Focus가 이동되지 않음)
    //1. The date is entered and the focus is moved to the inputCalendar on the right (previously Focus is not moved).
    WebSquare.wUnit.addCommand("assert", "scwin.isFocus()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 28-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
